-- Run only after the user approves credential installation and the matching edge release is deployed.
-- Generate a fresh 32-byte random token through the secure project tooling. Store the SAME value as:
--   edge secret FORMATION_SCHEDULER_TOKEN; Vault name formation_scheduler_token.
-- Never put the token in source, cron command text, logs, browser chat or review comments.
-- No token is generated by this script. It refuses to change jobs if setup is incomplete.
DO $$
DECLARE original_command text; anon_bearer text; target_url text; claim jsonb; payload text;
BEGIN
  IF (SELECT count(*) FROM vault.secrets WHERE name = 'formation_scheduler_token') <> 1 THEN
    RAISE EXCEPTION 'matching_scheduler_secret_required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM vault.decrypted_secrets WHERE name='formation_scheduler_token' AND decrypted_secret ~ '^[a-f0-9]{64}$') THEN
    RAISE EXCEPTION 'invalid_scheduler_secret_format';
  END IF;
  SELECT command INTO original_command FROM cron.job WHERE jobname='send-morning-nudges';
  IF original_command IS NULL THEN RAISE EXCEPTION 'existing_morning_job_required'; END IF;
  anon_bearer := substring(original_command FROM 'Bearer ([A-Za-z0-9_.-]+)');
  target_url := substring(original_command FROM '(https://[a-z0-9]+[.]supabase[.]co/functions/v1/send-daily-nudge)');
  IF target_url IS NULL OR anon_bearer IS NULL THEN RAISE EXCEPTION 'existing_scheduler_configuration_not_recognized'; END IF;
  payload := translate(split_part(anon_bearer,'.',2),'-_','+/');
  claim := convert_from(decode(payload || repeat('=', (4 - length(payload) % 4) % 4),'base64'),'UTF8')::jsonb;
  IF claim->>'role' IS DISTINCT FROM 'anon' THEN RAISE EXCEPTION 'expected_existing_public_anon_bearer'; END IF;
  -- Both legacy jobs invoked the same hourly morning selection. Keep a single runner.
  PERFORM cron.unschedule(jobid) FROM cron.job WHERE jobname IN ('send-morning-nudges','send-evening-nudges');
  PERFORM cron.schedule('send-morning-nudges','5 * * * *',format(
    'SELECT net.http_post(url := %L, headers := jsonb_build_object(''Content-Type'',''application/json'',''Authorization'',%L,''x-formation-scheduler-token'',(SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name=''formation_scheduler_token'')), body := ''{"scheduled":true}''::jsonb);',
    target_url, 'Bearer ' || anon_bearer));
END $$;
